
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_mscan_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_mscan", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.656286487332647e-02, -2.651927297209901e-02, -2.645495739804463e-02, -2.635906377179759e-02, -2.621404226875832e-02, -2.599075558626770e-02, -2.564064111920476e-02, -2.509190780060523e-02, -2.433916057187824e-02, -2.482032216263896e-02, -3.036125814214609e-02, -4.668222446019496e-02, -4.249445439086100e-02, -2.982011195941150e-02, -2.587073756335830e-02, -1.657776298905389e-02, -8.124266398639836e-03, -2.701183251211838e-03, -4.832540356260261e-04, -2.765303604353689e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


